import {approachDrone,DRONE_VOICES} from './approach-audio.mjs';
export class Sound{constructor(){this.enabled=true;this.ctx=null;}init(){if(this.ctx){this.ctx.resume().catch(()=>{});return;}try{const AC=globalThis.AudioContext||globalThis.webkitAudioContext;if(!AC)return;const c=this.ctx=new AC();this.master=c.createGain();this.master.gain.value=this.enabled?.45:0;this.master.connect(c.destination);let buffer=c.createBuffer(1,c.sampleRate*2,c.sampleRate),d=buffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;this.noise=c.createBufferSource();this.noise.buffer=buffer;this.noise.loop=true;const f=c.createBiquadFilter();f.type='bandpass';f.frequency.value=1700;f.Q.value=.65;this.jet=c.createGain();this.jet.gain.value=0;this.noise.connect(f).connect(this.jet).connect(this.master);this.noise.start();this.motor=c.createOscillator();this.motor.type='triangle';this.motor.frequency.value=55;this.engine=c.createGain();this.engine.gain.value=0;this.motor.connect(this.engine).connect(this.master);this.motor.start();
this.drone=c.createGain();this.drone.gain.value=0;this.drone.connect(this.master);
this.droneVoices=DRONE_VOICES.map(spec=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=48*spec.ratio+spec.offset;g.gain.value=spec.gain;o.connect(g).connect(this.drone);o.start();return {o,...spec};});}catch{this.ctx=null;}}toggle(){this.enabled=!this.enabled;if(this.master)this.master.gain.setTargetAtTime(this.enabled?.45:0,this.ctx.currentTime,.08);}update(s,paused,mission=null){if(!this.ctx)return;const t=this.ctx.currentTime;
const bed=approachDrone(mission,s.phase==='playing'&&s.spaceReached&&!s.grounded);
this.drone.gain.setTargetAtTime(paused||!this.enabled?0:bed.gain,t,paused||!bed.gain?.06:.35);
for(const voice of this.droneVoices)voice.o.frequency.setTargetAtTime(bed.frequency*voice.ratio+voice.offset,t,.6);
let active=!paused&&s.phase==='playing';this.jet.gain.setTargetAtTime(active?(s.rear+s.front)*.13+s.rocket*.32:0,t,.035);this.engine.gain.setTargetAtTime(active?(s.rocket?.13:s.grounded?Math.min(.08,Math.abs(s.vx)*.0003):0):0,t,.08);this.motor.frequency.setTargetAtTime(s.rocket?35:48+Math.abs(s.vx)*.4,t,.08);}tone(freq,dur,gain=.15,type='sine',delay=0){if(!this.ctx||!this.enabled)return;let c=this.ctx,t=c.currentTime+delay,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(gain,t);g.gain.exponentialRampToValueAtTime(.001,t+dur);o.connect(g).connect(this.master);o.start(t);o.stop(t+dur);}impact(speed){this.tone(65,.18,Math.min(.45,speed/350),'triangle');this.tone(140,.09,.08);}win(){[523,659,784,1047].forEach((f,i)=>this.tone(f,.4,.13,'sine',i*.1));}crash(){this.tone(90,.45,.5,'sawtooth');this.tone(42,.6,.25);}
loadClip(name){this.clips??={};this.clipLoading??={};this.clipFailed??={};if(!this.ctx||this.clips[name]||this.clipLoading[name]||this.clipFailed[name])return;this.clipLoading[name]=fetch(new URL('./'+name,import.meta.url)).then(r=>{if(!r.ok)throw new Error(name);return r.arrayBuffer();}).then(b=>this.ctx.decodeAudioData(b)).then(buf=>{this.clips[name]=buf;}).catch(()=>{this.clipFailed[name]=true;});}
playClip(name,gain){if(!this.enabled||!this.ctx||this.clipFailed?.[name])return 'skip';if(!this.clips?.[name]){this.loadClip(name);return 'wait';}const src=this.ctx.createBufferSource(),g=this.ctx.createGain();g.gain.value=gain;src.buffer=this.clips[name];src.connect(g).connect(this.master);src.start();return 'played';}
yuppie(){return this.playClip('yipee_l.mp3',1.35);}
laser(){return this.playClip('laser-sfx.mp3',1.2);}}
